// PRD 04 D14: every shipped model, audio file and look HDRI has a build-readable rights record
// (src/assets/rights-manifest.ts, generated by tools/gen-rights-manifest.mjs).
import { describe, expect, it } from "vitest";
import { AUDIO_MANIFEST } from "../../../src/audio-manifest.js";
import { MODEL_INFO, MODEL_KEYS, modelRef } from "../../../src/aura-assets.js";
import { AUDIO_RIGHTS, ENVIRONMENT_RIGHTS, MODEL_RIGHTS, PROCEDURAL_RIGHTS } from "../../../src/assets/rights-manifest.js";
import { LOOK_HDRI_FILES } from "../../../src/scenes/looks.js";

describe("rights manifest", () => {
  it("has one record per admitted model, with its file and sha256", () => {
    const admitted = MODEL_KEYS.filter((key) => MODEL_INFO[key].admitted);
    expect(MODEL_RIGHTS.map((record) => record.key).sort()).toEqual([...admitted].sort());
    for (const record of MODEL_RIGHTS) {
      const ref = modelRef(record.key as (typeof MODEL_KEYS)[number]);
      expect(ref?.url.endsWith(record.file.replace(/^src\//, "")), record.key).toBe(true);
      const hash = (ref?.sha256 ?? ref?.hash ?? "").replace(/^sha256-/, "");
      expect(hash, record.key).toBe(record.sha256);
      expect(record.license, record.key).toMatch(/\S/);
      expect(record.review, record.key).toMatch(/^approved by /);
    }
  });

  it("lists every procedural model as drawn from scene geometry", () => {
    const procedural = MODEL_KEYS.filter((key) => MODEL_INFO[key].procedural);
    expect(PROCEDURAL_RIGHTS.map((record) => record.key).sort()).toEqual([...procedural].sort());
  });

  it("has a record for every recorded audio file, none of them free-tier", () => {
    for (const kind of ["lines", "songs", "beds", "sfx"] as const) {
      const recorded = Object.keys(AUDIO_MANIFEST[kind]).sort();
      expect(AUDIO_RIGHTS[kind].files.map((file) => file.id).sort(), kind).toEqual(recorded);
      expect(Object.keys(AUDIO_RIGHTS[kind].tiers), kind).not.toContain("free");
    }
  });

  it("has a CC0 record for each look HDRI", () => {
    expect(ENVIRONMENT_RIGHTS.map((record) => record.file).sort()).toEqual([...LOOK_HDRI_FILES].sort());
    for (const record of ENVIRONMENT_RIGHTS) expect(record.license).toMatch(/CC0/);
  });
});
